head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useFilterSearch]\nFilterList 에 검색어 필터 기능을 포함할지 설정합니다.",
    "validation" : [
        "Column 의 useFilter 속성으로 FilterList 기능이 적용된 경우에 동작합니다.",
    ]
}



scwin.onpageload = async function () {
    // 공통 Global DataList 생성
    $c.gcm.createCommonDatalist();

    // 정적 select1 기본값 설정 (gdl_boolean : 1=미설정, 2=true, 3=false)
    con_useFilterSearch.setValue("2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 현재 설정/검증 안내 라벨 (target 생성 전 가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] 전체 Header Column 은 useFilter=true 고정이며 GridView 는 useFilterList=true 고정이다.';
    lbl += '\n   즉 Column 의 useFilter 속성으로 FilterList 기능이 적용된 상태이다.';
    lbl += '\n[절차] con 에서 useFilterSearch 값 선택 -> (Target 재생성) -> col1 헤더의 필터 버튼 클릭으로 FilterList 를 연다.';
    lbl += '\n   -> FilterList 검색어 입력창에 값(예: an)을 입력한다. col1 값은 apple / banana / grape / orange 이다.';
    lbl += '\n[확인] (FilterList 표시목록 출력) 클릭 시 검색 입력창 유무와 현재 FilterList 표시목록이 결과창에 출력된다.';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    // 조건 값 조회 (gdl_boolean 바인딩이므로 getText 사용)
    let cUseFilterSearch = con_useFilterSearch.getText();
    let attrUseFilterSearch = (cUseFilterSearch === '') ? '' : ' useFilterSearch="' + cUseFilterSearch + '"';

    // dataList 직접 생성 (col1 = 부분 일치 확인용 4종 값)
    let ns = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + ns + ' id="dlt_bind" baseNode="list" repeatNode="map" saveRemovedData="true">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true"></w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);
    let arrDl = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDl[arrDl.length - 1];

    let cats = ["apple", "banana", "grape", "orange"];
    let types = ["X", "Y"];
    let jsonData = [];
    for (let i = 0; i < 12; i++) {
        jsonData.push({
            "col1": cats[i % 4],
            "col2": types[Math.floor(i / 3) % 2],
            "col3": "name_" + (i + 1),
            "col4": "" + (i + 1)
        });
    }
    scwin.dlt_bind.setJSON(jsonData, false);

    // target 생성 : 전체 Header Column 은 useFilter=true 고정 (FilterList 기능 적용 전제)
    let grp_comp = $c.gcm.getTestGroup();
    let s = '';
    s += '<w2:gridView ' + ns + attrUseFilterSearch + ' useFilterList="true" dataList="data:dlt_bind" checkAllType="false" id="" style="width:430px;height:220px;">';
    s += '<w2:caption style="" id="caption1" value="useFilterSearch 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="100" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="110" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" id="column4" value="col4" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="110" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 현재 FilterList 상태(검색 입력창 유무 / 검색어 / 표시목록) 출력
scwin.btn_dumpFilterList_onclick = function () {
    let sv = function (s) { wf_body_bottom.getObj("scwin").setReturnValue(s); };
    let list = target1.customFilterList;

    if (!list) {
        sv("===== FilterList 미생성 ===== col1 헤더의 필터 버튼을 먼저 클릭하세요.");
        return;
    }

    let input = (list.dom) ? list.dom.input : null;
    sv("===== FilterList 상태 ===== 검색 입력창 : " + (input ? "있음" : "없음") + " / 검색어 : " + (input ? input.value : "-"));

    // FilterList 표시목록 (index 0 = 사용자필터, index 1 = 전체선택 이므로 데이터 아이템만 출력)
    let data = list.getAllData();
    let cnt = 0;
    for (let i = 2; i < data.length; i++) {
        sv("  - " + data[i].id2 + " : " + (data[i].id1 ? "체크" : "해제"));
        cnt++;
    }
    sv("  (표시 아이템 " + cnt + "개)");
}
